// ReelParty iPad Edition: EIN DATEI, KEINE INSTALLATION NOETIG
// Deployment: Node.js 20+; Build: echo ready; Start: node server.js
// Auto-generated standalone version; original source in ReelParty-iPad.zip
"use strict";

// ReelParty - server without npm dependencies (Node.js >=20)
const http = require("node:http");
const crypto = require("node:crypto");

const MAX_PEOPLE = 4;
const MAX_REELS = 80;
const ROOM_TTL_MS = 20 * 60 * 1000;
const STREAM_GRACE_MS = 25 * 1000;
const ROOM_CHARS = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
// Statische Assets sind direkt in dieser Datei eingebettet.
const assetTypes = { "/": "text/html", "/index.html": "text/html", "/styles.css": "text/css", "/app.js": "text/javascript", "/icon.svg": "image/svg+xml", "/manifest.webmanifest": "application/manifest+json" };

const ASSET_DATA = {"index.html":"","styles.css":"","app.js":"","icon.svg":"","manifest.webmanifest":""};

function cleanName(value) {
  return typeof value === "string" ? value.trim().replace(/\s+/g, " ").slice(0, 24) : "";
}
function parseInstagramReel(value) {
  if (typeof value !== "string" || value.length > 2000) return null;
  try {
    const url = new URL(value.trim());
    if (url.protocol !== "https:" || !["www.instagram.com", "instagram.com", "m.instagram.com"].includes(url.hostname.toLowerCase())) return null;
    const match = url.pathname.match(/^\/(?:reel|reels)\/([A-Za-z0-9_-]{5,32})(?:\/|$)/);
    return match ? `https://www.instagram.com/reel/${match[1]}/` : null;
  } catch { return null; }
}

function createReelPartyServer() {
  const rooms = new Map();
  const tokens = new Map();
  const timers = new Set();

  function generateCode() {
    let code;
    do {
      code = Array.from(crypto.randomBytes(8), n => ROOM_CHARS[n % ROOM_CHARS.length]).join("");
    } while (rooms.has(code));
    return code;
  }

  function snapshot(room) {
    return {
      code: room.code,
      hostId: room.hostId,
      participants: Array.from(room.members.values(), member => ({ id: member.id, name: member.name, isHost: room.hostId === member.id })),
      queue: room.queue, currentIndex: room.currentIndex, messages: room.messages
    };
  }

  function streamEvent(res, type, payload) {
    if (!res || res.destroyed || res.writableEnded) return;
    try { res.write(`event: ${type}\ndata: ${JSON.stringify(payload)}\n\n`); }
    catch { /* Browser may have disconnected */ }
  }

  function broadcast(room, type, payload) {
    for (const member of room.members.values()) streamEvent(member.stream, type, payload);
  }

  function publish(room) { broadcast(room, "room-state", snapshot(room)); }

  function addMember(room, name) {
    if (!name) return { ok: false, error: "Bitte gib einen Namen ein." };
    if (room.members.size >= MAX_PEOPLE) return { ok: false, error: "Dieser Raum ist voll (maximal 4 Personen)." };
    const member = { id: crypto.randomUUID(), token: crypto.randomBytes(32).toString("hex"), name, room, stream: null, disconnectedAt: Date.now(), rates: {} };
    room.members.set(member.id, member);
    room.emptyAt = null;
    room.hostId ||= member.id;
    tokens.set(member.token, member);
    publish(room);
    return { ok: true, code: room.code, selfId: member.id, token: member.token, state: snapshot(room) };
  }

  function removeMember(member) {
    if (!member || !tokens.has(member.token)) return;
    const room = member.room;
    tokens.delete(member.token);
    room.members.delete(member.id);
    const stream = member.stream;
    member.stream = null;
    if (stream && !stream.destroyed) stream.end();
    if (room.hostId === member.id) room.hostId = room.members.keys().next().value || null;
    if (!room.members.size) room.emptyAt = Date.now();
    else publish(room);
  }

  function allowRate(member, kind, interval) {
    const previous = member.rates[kind] || 0;
    if (Date.now() - previous < interval) return false;
    member.rates[kind] = Date.now();
    return true;
  }

  function action(member, command, payload = {}) {
    const room = member.room;
    if (!room.members.has(member.id)) return { ok: false, error: "Nicht mehr im Raum." };
    const hostOnly = ["queue:remove", "reel:select", "reel:step"];
    if (hostOnly.includes(command) && room.hostId !== member.id) return { ok: false, error: "Nur die Moderation kann Reels wechseln oder entfernen." };

    if (command === "queue:add") {
      if (room.queue.length >= MAX_REELS) return { ok: false, error: "Die Warteschlange ist voll (80 Reels)." };
      const url = parseInstagramReel(payload?.url);
      if (!url) return { ok: false, error: "Bitte einen gültigen öffentlichen Instagram-Reel-Link eingeben." };
      if (!allowRate(member, "add", 600)) return { ok: false, error: "Bitte kurz warten." };
      room.queue.push({ id: crypto.randomUUID(), url, by: member.name, at: Date.now() });
      if (room.currentIndex < 0) room.currentIndex = 0;
      publish(room);
      return { ok: true };
    }
    if (command === "queue:remove") {
      const index = room.queue.findIndex(entry => entry.id === payload?.id);
      if (index < 0) return { ok: false, error: "Reel nicht gefunden." };
      room.queue.splice(index, 1);
      if (!room.queue.length) room.currentIndex = -1;
      else if (index < room.currentIndex) room.currentIndex--;
      else if (index === room.currentIndex) room.currentIndex = Math.min(index, room.queue.length - 1);
      publish(room);
      return { ok: true };
    }
    if (command === "reel:select") {
      if (!Number.isInteger(payload?.index) || payload.index < 0 || payload.index >= room.queue.length) return { ok: false, error: "Ungültiges Reel." };
      room.currentIndex = payload.index;
      publish(room);
      return { ok: true };
    }
    if (command === "reel:step") {
      if (payload?.delta !== 1 && payload?.delta !== -1) return { ok: false, error: "Ungültige Richtung." };
      const next = room.currentIndex + payload.delta;
      if (next < 0 || next >= room.queue.length) return { ok: false, error: "Hier endet die Warteschlange." };
      room.currentIndex = next;
      publish(room);
      return { ok: true };
    }
    if (command === "chat:send") {
      if (!allowRate(member, "chat", 350)) return { ok: false, error: "Bitte kurz warten." };
      const text = typeof payload?.text === "string" ? payload.text.trim().slice(0, 320) : "";
      if (!text) return { ok: false, error: "Nachricht ist leer." };
      const message = { id: crypto.randomUUID(), by: member.name, authorId: member.id, text, at: Date.now() };
      room.messages.push(message);
      if (room.messages.length > 80) room.messages.shift();
      broadcast(room, "chat-message", message);
      return { ok: true };
    }
    return { ok: false, error: "Aktion nicht unterstützt." };
  }

  function json(res, code, data) {
    res.writeHead(code, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" });
    res.end(JSON.stringify(data));
  }

  async function readJson(req) {
    let body = "";
    for await (const chunk of req) {
      body += chunk.toString("utf8");
      if (body.length > 12_000) throw new Error("Anfrage zu groß.");
    }
    try { return JSON.parse(body); }
    catch { throw new Error("Ungültiges JSON."); }
  }

  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, "http://localhost");
    res.setHeader("X-Content-Type-Options", "nosniff");
    res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
    try {
      if (req.method === "GET" && url.pathname === "/health") return json(res, 200, { ok: true });

      if (req.method === "GET" && url.pathname === "/events") {
        const member = tokens.get(url.searchParams.get("token"));
        if (!member) return json(res, 401, { ok: false, error: "Sitzung abgelaufen." });
        res.writeHead(200, { "Content-Type": "text/event-stream; charset=utf-8", "Cache-Control": "no-cache, no-transform", "Connection": "keep-alive", "X-Accel-Buffering": "no", "X-Content-Type-Options": "nosniff" });
        res.write("retry: 1500\n\n");
        if (member.stream && member.stream !== res) member.stream.end();
        member.stream = res;
        member.disconnectedAt = null;
        streamEvent(res, "room-state", snapshot(member.room));
        res.on("close", () => { if (member.stream === res) { member.stream = null; member.disconnectedAt = Date.now(); } });
        return;
      }

      if (req.method === "POST" && url.pathname.startsWith("/api/")) {
        const data = await readJson(req);
        if (url.pathname === "/api/create") {
          const name = cleanName(data?.name);
          if (!name) return json(res, 400, { ok: false, error: "Bitte gib einen Namen ein." });
          const code = generateCode();
          const room = { code, members: new Map(), hostId: null, queue: [], currentIndex: -1, messages: [], emptyAt: null };
          rooms.set(code, room);
          return json(res, 200, addMember(room, name));
        }
        if (url.pathname === "/api/join") {
          const code = typeof data?.code === "string" ? data.code.trim().toUpperCase() : "";
          const room = rooms.get(code);
          if (!room) return json(res, 404, { ok: false, error: "Raum nicht gefunden. Prüfe den Code oder erstelle einen neuen Raum." });
          return json(res, 200, addMember(room, cleanName(data?.name)));
        }
        const member = tokens.get(data?.token);
        if (!member) return json(res, 401, { ok: false, error: "Deine Sitzung ist abgelaufen. Bitte erneut beitreten." });
        if (url.pathname === "/api/resume") {
          member.disconnectedAt = Date.now(); // Keep reservation until the event stream reconnects.
          return json(res, 200, { ok: true, code: member.room.code, selfId: member.id, token: member.token, state: snapshot(member.room) });
        }
        if (url.pathname === "/api/leave") {
          removeMember(member);
          return json(res, 200, { ok: true });
        }
        if (url.pathname === "/api/action") return json(res, 200, action(member, data?.action, data?.payload));
      }
      if (req.method === "GET" && Object.hasOwn(assetTypes, url.pathname)) {
        const file = url.pathname === "/" ? "index.html" : url.pathname.slice(1);
        res.writeHead(200, { "Content-Type": assetTypes[url.pathname] + "; charset=utf-8", "Cache-Control": "no-cache" });
        res.end(Buffer.from(ASSET_DATA[file], "base64"));
        return;
      }
      json(res, 404, { ok: false, error: "Nicht gefunden." });
    } catch (error) {
      if (!res.headersSent) json(res, 400, { ok: false, error: error.message || "Fehler bei Anfrage." });
    }
  });

  const sweeper = setInterval(() => {
    const now = Date.now();
    for (const room of rooms.values()) {
      for (const member of Array.from(room.members.values())) {
        if (member.disconnectedAt && now - member.disconnectedAt > STREAM_GRACE_MS) removeMember(member);
        else if (member.stream && !member.stream.destroyed) member.stream.write(": heartbeat\n\n");
      }
      if (room.emptyAt && now - room.emptyAt > ROOM_TTL_MS) rooms.delete(room.code);
    }
  }, 10_000);
  sweeper.unref();

  return {
    server, rooms, tokens,
    start(port = Number(process.env.PORT) || 3000) {
      return new Promise(resolve => server.listen(port, "0.0.0.0", () => resolve(server.address().port)));
    },
    stop() {
      clearInterval(sweeper);
      for (const member of tokens.values()) if (member.stream) member.stream.end();
      return new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
    }
  };
}

if (require.main === module) {
  createReelPartyServer().start().then(port => console.log(`ReelParty läuft auf http://localhost:${port}`));
}

module.exports = { createReelPartyServer, parseInstagramReel, MAX_PEOPLE };
